// === Tab: mySketch ===
// Gumowski-Mira Attractor 
setup = _ => {
	createCanvas(1112, 834)
	colorMode(HSB, 255)
	w = max(width, height)
	x = y = 0
  sca1e=w/36
	strokeWeight(2);
	background(w);
}

draw = _ => {
	background(w, 10)
	translate(width / 2, height / 2)
	x++
	for (i = 5e3; i--;) {
		tmp = y - .97 * x + 5 / (1 + x * x) - 5
		y = -.995 * x
		x = tmp
		stroke(i/20%255, 255, 255);
		point(x * sca1e, y * sca1e)
	}
}

let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save('pix.jpg');
    lapse = millis();
  }
}

